import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

// Helper to create and issue an invoice
function createAndIssueInvoice(customerId, issueDate, lines, terms = 'NET30') {
  const draftResult = createInvoice({
    customerId,
    issueDate,
    lines,
    terms,
  });
  if (!draftResult.ok) throw new Error(`Failed to create invoice: ${draftResult.error}`);

  const issuedResult = issueInvoice(draftResult.value, []);
  if (!issuedResult.ok) throw new Error(`Failed to issue invoice: ${issuedResult.error}`);

  return issuedResult.value;
}

test('exportCsv returns string', () => {
  const csv = exportCsv([]);
  assert.equal(typeof csv, 'string');
});

test('exportCsv includes header', () => {
  const csv = exportCsv([]);
  assert(csv.includes('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
});

test('exportCsv header is first line', () => {
  const csv = exportCsv([]);
  const lines = csv.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv ends with newline', () => {
  const csv = exportCsv([]);
  assert(csv.endsWith('\n'));
});

test('exportCsv empty list returns only header and newline', () => {
  const csv = exportCsv([]);
  const expected = 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n';
  assert.equal(csv, expected);
});

test('exportCsv single invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 3); // header, data, trailing empty
  assert(lines[1].includes(invoice.number));
  assert(lines[1].includes('2025-01-15'));
});

test('exportCsv includes customer name', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  assert(csv.includes('Acme Corp'));
});

test('exportCsv includes issue date', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  assert(csv.includes('2025-01-15'));
});

test('exportCsv includes due date', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const csv = exportCsv([invoice]);
  assert(csv.includes('2025-01-29'));
});

test('exportCsv includes status', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  assert(csv.includes('issued'));
});

test('exportCsv formats amounts as euros', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  // Should include amounts like 10.00, 11.27, etc.
  assert(csv.includes('.'));
  assert(!/\d,\d/.test(csv)); // No thousands separator
});

test('exportCsv formats amounts with 2 decimals', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  // Check for pattern like X.XX
  assert(/\d+\.\d{2}/.test(dataLine));
});

test('exportCsv no currency sign', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  assert(!csv.includes('€'));
  assert(!csv.includes('$'));
});

test('exportCsv multiple invoices in order', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'ICON-SET', qty: 2 }]);

  const csv = exportCsv([invoice1, invoice2]);
  const lines = csv.split('\n');
  assert(lines[1].includes(invoice1.number));
  assert(lines[2].includes(invoice2.number));
});

test('exportCsv with draft invoice', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  assert.equal(draftResult.ok, true);

  const csv = exportCsv([draftResult.value]);
  assert(csv.includes('draft'));
});

test('exportCsv with paid invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const paymentResult = recordPayment(invoice, { amount: 1127, date: '2025-01-20' });
  assert.equal(paymentResult.ok, true);

  const csv = exportCsv([paymentResult.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  // Due should be 0.00
  assert(dataLine.endsWith('0.00'));
});

test('exportCsv with partially paid invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const paymentResult = recordPayment(invoice, { amount: 500, date: '2025-01-20' });
  assert.equal(paymentResult.ok, true);

  const csv = exportCsv([paymentResult.value]);
  assert(csv.includes('partially_paid'));
});

test('exportCsv customer with comma in name', () => {
  // C-002 has name "Beta Corp, Ltd." which contains a comma
  const invoice = createAndIssueInvoice('C-002', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  // Customer field should be quoted
  assert(dataLine.includes('"Beta Corp, Ltd."'));
});

test('exportCsv with discounts', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1, discountPercent: 10 },
  ]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  // Should have discount amount
  assert(dataLine.split(',').length === 10);
});

test('exportCsv subtotal field', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  // subtotal is field 5 (after: number, customer, issueDate, dueDate, status)
  assert(parseFloat(fields[5]) > 0);
});

test('exportCsv vat field', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  // vat is field 7 (after: number, customer, issueDate, dueDate, status, subtotal, discount)
  assert(parseFloat(fields[7]) > 0);
});

test('exportCsv total field', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  // total is field 8
  assert(parseFloat(fields[8]) > 0);
});

test('exportCsv due field for unpaid invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  // due (field 9) should equal total (field 8)
  assert.equal(fields[8], fields[9]);
});

test('exportCsv due field for paid invoice is zero', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const paymentResult = recordPayment(invoice, { amount: 1127, date: '2025-01-20' });
  const csv = exportCsv([paymentResult.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  // due (field 9) should be 0.00
  assert.equal(fields[9], '0.00');
});

test('exportCsv multiple invoices different customers', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-002', '2025-02-15', [{ sku: 'DES-HOUR', qty: 1 }]);

  const csv = exportCsv([invoice1, invoice2]);
  assert(csv.includes('Acme Corp'));
  assert(csv.includes('Beta Corp'));
});

test('exportCsv escapes double quotes in customer name', () => {
  // This would require a customer with quotes in name
  // For now, just verify the CSV is valid
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  assert.equal(typeof csv, 'string');
});

test('exportCsv lines have consistent field count', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'ICON-SET', qty: 2 }]);

  const csv = exportCsv([invoice1, invoice2]);
  const lines = csv.split('\n');
  const headerFields = lines[0].split(',').length;

  // Count fields in data lines (accounting for quoted fields)
  for (let i = 1; i < lines.length - 1; i++) {
    if (lines[i].length === 0) continue;
    // This is a simplified check - real CSV parsing would be more complex
    assert(lines[i].length > 0);
  }
});

test('exportCsv with empty dueDate', () => {
  // Draft invoices might have empty dueDate
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  assert.equal(draftResult.ok, true);
  // Remove dueDate to test empty field
  draftResult.value.dueDate = undefined;

  const csv = exportCsv([draftResult.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  // Should have empty field for dueDate
  assert(dataLine.includes(',,'));
});

test('exportCsv formatting consistency', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-001', '2025-01-20', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice1, invoice2]);
  const lines = csv.split('\n');

  // All amount fields should have 2 decimal places
  for (let i = 1; i < lines.length - 1; i++) {
    if (lines[i].length === 0) continue;
    const amountPattern = /\d+\.\d{2}/g;
    const matches = lines[i].match(amountPattern);
    assert(matches && matches.length >= 4, 'Should have at least 4 amounts with 2 decimals');
  }
});

test('exportCsv preserves invoice order', () => {
  const invoices = [];
  for (let i = 0; i < 5; i++) {
    invoices.push(
      createAndIssueInvoice('C-001', `2025-0${1 + Math.floor(i / 2)}-${10 + i}`, [
        { sku: 'ICON-SET', qty: i + 1 },
      ])
    );
  }

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');

  for (let i = 0; i < invoices.length; i++) {
    assert(lines[i + 1].includes(invoices[i].number));
  }
});

test('exportCsv with high amount', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1000 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  // Should have large amount formatted correctly
  assert(/\d{4,}\.\d{2}/.test(dataLine));
});

test('exportCsv with low amount', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1, discountPercent: 99 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  // Should format small amounts correctly
  assert(/0\.\d{2}/.test(dataLine));
});

test('exportCsv all fields present', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');
  const dataLine = lines[1];

  // Should have all 10 fields
  const fields = dataLine.split(',');
  assert(fields.length === 10);
});

